def cmp_semver(a: str, b: str) -> int:
    def parse(s: str):
        parts = s.split('.')
        while len(parts) < 3:
            parts.append('0')
        return [int(parts[0]), int(parts[1]), int(parts[2])]

    va = parse(a)
    vb = parse(b)
    for i in range(3):
        if va[i] < vb[i]:
            return -1
        elif va[i] > vb[i]:
            return 1
    return 0
